const handlers = new Map([
  ["render", (p) => renderReport(p.id)],
  ["flush",  () => flushCaches()],
]);

export async function invoke(envelope) {
  const handler = handlers.get(envelope.kind);   // allow-list, no prototype lookup
  if (!handler) throw new Error(`unknown command ${envelope.kind}`);
  return handler(envelope.payload ?? {});
}
